package com.retailflow.pos.stock;
import com.retailflow.pos.common.ApiResponse;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/stock") public class StockController{private final StockMovementService s;private final StockMovementRepository r;public StockController(StockMovementService s,StockMovementRepository r){this.s=s;this.r=r;}@GetMapping("/movements")public ApiResponse<?>list(@RequestParam(required=false)String productId){return ApiResponse.ok(productId==null?r.findAll():r.findByProductId(productId));}@GetMapping("/movements/recent")public ApiResponse<?>recent(@RequestParam(defaultValue="20")int limit){return ApiResponse.ok(s.recent(limit));}@GetMapping("/valuation")public ApiResponse<?>valuation(){return ApiResponse.ok(s.valuation());}}
